29	use std::fmt::Display;
30	use std::ops::{Deref, Range};
31	use std::str::FromStr;
32	
33	use serde::{Deserialize, Serialize};
34	use typst_syntax::{DiagSpan, DiagSpanKind, FileId, Source};
35	use typst_utils::{LazyHash, SmallBitSet};
36	
37	use crate::diag::FileResult;
38	use crate::format::Format;
39	use crate::foundations::{
40	    Array, Binding, Bytes, Datetime, Dict, Duration, Module, NativeRuleMap, Scope, Styles,
41	};
42	use crate::layout::{Alignment, Dir};
43	use crate::routines::Routines;
44	use crate::text::{Font, FontBook};
45	use crate::visualize::Color;
