47	/// The environment in which typesetting occurs.
48	///
49	/// All loading functions (`main`, `source`, `file`, `font`) should perform
50	/// internal caching so that they are relatively cheap on repeated invocations
51	/// with the same argument. [`Source`], [`Bytes`], and [`Font`] are
52	/// all reference-counted and thus cheap to clone.
53	///
54	/// The compiler doesn't do the caching itself because the world has much more
55	/// information on when something can change. For example, fonts typically don't
56	/// change and can thus even be cached across multiple compilations (for
57	/// long-running applications like `typst watch`). Source files on the other
58	/// hand can change and should thus be cleared after each compilation. Advanced
59	/// clients like language servers can also retain the source files and
60	/// [edit](Source::edit) them in-place to benefit from better incremental
61	/// performance.
62	#[comemo::track]
63	pub trait World: Send + Sync {
64	    /// The standard library.
65	    ///
66	    /// Can be created through `Library::build()`.
67	    fn library(&self) -> &LazyHash<Library>;
68	
69	    /// Metadata about all known fonts.
70	    fn book(&self) -> &LazyHash<FontBook>;
71	
72	    /// Get the file id of the main source file.
73	    fn main(&self) -> FileId;
74	
75	    /// Try to access the specified file location as a source file.
76	    fn source(&self, id: FileId) -> FileResult<Source>;
77	
78	    /// Try to access the specified file.
79	    ///
80	    /// For file locations for which [`source`](Self::source) succeeds, this
81	    /// should also succeed. The [`Bytes`] can be cheaply created as a view into
82	    /// an existing [`Source`] through [`Bytes::from_string`].
83	    fn file(&self, id: FileId) -> FileResult<Bytes>;
84	
85	    /// Try to access the font with the given index in the font book.
86	    ///
87	    /// Note that the index is not guaranteed to be in bounds of the font book
88	    /// returned by this world's `book()` function. This is the case because
89	    /// this function may be invoked with indices from an outdated or different
90	    /// font book during incremental compilation validation.
91	    fn font(&self, index: usize) -> Option<Font>;
92	
93	    /// Get the current date.
94	    ///
95	    /// If no offset is specified, the local date should be chosen. Otherwise,
96	    /// the UTC date should be chosen with the corresponding offset.
97	    ///
98	    /// If this function returns `None`, Typst's `datetime` function will
99	    /// return an error.
100	    fn today(&self, offset: Option<Duration>) -> Option<Datetime>;
101	}
102	
103	macro_rules! world_impl {
104	    ($W:ident for $ptr:ty) => {
105	        impl<$W: World> World for $ptr {
106	            fn library(&self) -> &LazyHash<Library> {
107	                self.deref().library()
108	            }
109	
110	            fn book(&self) -> &LazyHash<FontBook> {
111	                self.deref().book()
112	            }
113	
114	            fn main(&self) -> FileId {
115	                self.deref().main()
116	            }
117	
118	            fn source(&self, id: FileId) -> FileResult<Source> {
119	                self.deref().source(id)
120	            }
121	
122	            fn file(&self, id: FileId) -> FileResult<Bytes> {
123	                self.deref().file(id)
124	            }
125	
126	            fn font(&self, index: usize) -> Option<Font> {
127	                self.deref().font(index)
128	            }
129	
130	            fn today(&self, offset: Option<Duration>) -> Option<Datetime> {
131	                self.deref().today(offset)
132	            }
133	        }
134	    };
135	}
136	
137	world_impl!(W for std::boxed::Box<W>);
138	world_impl!(W for std::sync::Arc<W>);
139	world_impl!(W for &W);
140	
141	/// Helper methods on [`World`] implementations.
142	pub trait WorldExt {
143	    /// Get the byte range for a span.
144	    ///
145	    /// Returns `None` if the `Span` does not point into any file.
146	    fn range(&self, span: impl Into<DiagSpan>) -> Option<Range<usize>>;
147	}
148	
149	impl<T: World + ?Sized> WorldExt for T {
150	    fn range(&self, span: impl Into<DiagSpan>) -> Option<Range<usize>> {
151	        match span.into().get() {
152	            DiagSpanKind::Detached => None,
153	            DiagSpanKind::Number { id, num, sub_range } => {
154	                self.source(id).ok()?.range(num, sub_range)
155	            }
156	            DiagSpanKind::Range { id: _, range } => Some(range),
157	        }
158	    }
159	}
