161	/// Definition of Typst's standard library.
162	///
163	/// To create and configure the standard library, use the `LibraryExt` trait
164	/// and call
165	/// - `Library::default()` for a standard configuration
166	/// - `Library::builder().build()` if you want to customize the library
167	#[derive(Debug, Clone, Hash)]
168	#[non_exhaustive]
169	pub struct Library {
170	    /// Defines implementation of various Typst compiler routines as a table of
171	    /// function pointers.
172	    pub routines: &'static Routines,
173	    /// The module that contains the definitions that are available everywhere.
174	    pub global: Module,
175	    /// The module that contains the definitions available in math mode.
176	    pub math: Module,
177	    /// The default style properties (for page size, font selection, and
178	    /// everything else configurable via set and show rules).
179	    pub styles: Styles,
180	    /// The built-in show rules.
181	    pub rules: NativeRuleMap,
182	    /// The standard library as a value. Used to provide the `std` module.
183	    pub std: Binding,
184	    /// In-development features that were enabled.
185	    pub features: Features,
186	    /// Registered [export formats](crate::format).
187	    pub formats: Vec<Format>,
188	}
189	
190	/// Configurable builder for the standard library.
191	///
192	/// Constructed via the `LibraryExt` trait.
193	#[derive(Debug, Clone)]
194	pub struct LibraryBuilder {
195	    routines: &'static Routines,
196	    inputs: Option<Dict>,
197	    features: Features,
198	    formats: Vec<Format>,
199	}
200	
201	impl LibraryBuilder {
202	    /// Creates a new builder.
203	    #[doc(hidden)]
204	    pub fn from_routines(
205	        routines: &'static Routines,
206	        formats: impl IntoIterator<Item = Format>,
207	    ) -> Self {
208	        Self {
209	            routines,
210	            inputs: None,
211	            features: Features::default(),
212	            formats: formats.into_iter().collect(),
213	        }
214	    }
215	
216	    /// Configure the inputs visible through `sys.inputs`.
217	    pub fn with_inputs(mut self, inputs: Dict) -> Self {
218	        self.inputs = Some(inputs);
219	        self
220	    }
221	
222	    /// Configure in-development features that should be enabled.
223	    ///
224	    /// No guarantees whatsover!
225	    pub fn with_features(mut self, features: Features) -> Self {
226	        self.features = features;
227	        self
228	    }
229	
230	    /// Consumes the builder and returns a `Library`.
231	    pub fn build(self) -> Library {
232	        let math = math::module();
233	        let inputs = self.inputs.unwrap_or_default();
234	        let global = global(&self.formats, math.clone(), inputs);
235	        let mut rules = (self.routines.rules)();
236	        for format in &self.formats {
237	            format.register_rules(&mut rules);
238	        }
239	        Library {
240	            routines: self.routines,
241	            global: global.clone(),
242	            math,
243	            styles: Styles::new(),
244	            rules,
245	            std: Binding::detached(global),
246	            features: self.features,
247	            formats: self.formats,
248	        }
249	    }
250	}
251	
252	/// A selection of in-development features that should be enabled.
253	///
254	/// Can be collected from an iterator of [`Feature`]s.
255	#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
256	pub struct Features(SmallBitSet);
257	
258	impl Features {
259	    /// Creates an instance where all features are enabled.
260	    pub fn all() -> Self {
261	        Feature::all().collect()
262	    }
263	
264	    /// Creates an instance where no features are enabled.
265	    pub fn none() -> Self {
266	        Self::default()
267	    }
268	
269	    /// Check whether the given feature is enabled.
270	    pub fn is_enabled(&self, feature: Feature) -> bool {
271	        self.0.contains(feature as usize)
272	    }
273	}
274	
275	impl FromIterator<Feature> for Features {
276	    fn from_iter<T: IntoIterator<Item = Feature>>(iter: T) -> Self {
277	        let mut set = SmallBitSet::default();
278	        for feature in iter {
279	            set.insert(feature as usize);
280	        }
281	        Self(set)
282	    }
283	}
284	
285	/// An in-development feature that should be enabled.
286	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
287	#[non_exhaustive]
288	pub enum Feature {
289	    Html,
290	    Bundle,
291	    A11yExtras,
292	}
293	
294	impl Feature {
295	    /// Iterates over all available features.
296	    pub fn all() -> impl Iterator<Item = Self> {
297	        [Self::Html, Self::Bundle, Self::A11yExtras].into_iter()
298	    }
299	}
300	
301	impl Display for Feature {
302	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
303	        f.write_str(match self {
304	            Feature::Html => "html",
305	            Feature::Bundle => "bundle",
306	            Feature::A11yExtras => "a11y-extras",
307	        })
308	    }
309	}
310	
311	impl FromStr for Feature {
312	    type Err = ();
313	
314	    fn from_str(s: &str) -> Result<Self, Self::Err> {
315	        match s {
316	            "html" => Ok(Self::Html),
317	            "bundle" => Ok(Self::Bundle),
318	            "a11y-extras" => Ok(Self::A11yExtras),
319	            _ => Err(()),
320	        }
321	    }
322	}
323	
324	/// A group of related standard library definitions.
325	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash, Serialize, Deserialize)]
326	#[serde(rename_all = "kebab-case")]
327	pub enum Category {
328	    Foundations,
329	    Introspection,
330	    Layout,
331	    DataLoading,
332	    Math,
333	    Model,
334	    Symbols,
335	    Text,
336	    Visualize,
337	    Format,
338	    Pdf,
339	    Html,
340	    Svg,
341	    Png,
342	    Bundle,
343	}
344	
345	impl Category {
346	    /// The kebab-case name of the category.
347	    pub fn name(&self) -> &'static str {
348	        match self {
349	            Self::Foundations => "foundations",
350	            Self::Introspection => "introspection",
351	            Self::Layout => "layout",
352	            Self::DataLoading => "data-loading",
353	            Self::Math => "math",
354	            Self::Model => "model",
355	            Self::Symbols => "symbols",
356	            Self::Text => "text",
357	            Self::Visualize => "visualize",
358	            Self::Format => "format",
359	            Self::Pdf => "pdf",
360	            Self::Html => "html",
361	            Self::Svg => "svg",
362	            Self::Png => "png",
363	            Self::Bundle => "bundle",
364	        }
365	    }
366	}
367	
368	/// Construct the module with global definitions.
369	fn global(formats: &[Format], math: Module, inputs: Dict) -> Module {
370	    let mut global = Scope::deduplicating();
371	
372	    self::foundations::define(&mut global, inputs);
373	    self::model::define(&mut global);
374	    self::text::define(&mut global);
375	    self::layout::define(&mut global);
376	    self::visualize::define(&mut global);
377	    self::introspection::define(&mut global);
378	    self::loading::define(&mut global);
379	    self::symbols::define(&mut global);
380	    global.define("format", self::format::module(formats));
381	    global.define("math", math);
382	
383	    prelude(&mut global);
384	
385	    Module::new("global", global)
386	}
387	
388	/// Defines scoped values that are globally available, too.
389	fn prelude(global: &mut Scope) {
390	    global.define("black", Color::BLACK);
391	    global.define("gray", Color::GRAY);
392	    global.define("silver", Color::SILVER);
393	    global.define("white", Color::WHITE);
394	    global.define("navy", Color::NAVY);
395	    global.define("blue", Color::BLUE);
396	    global.define("aqua", Color::AQUA);
397	    global.define("teal", Color::TEAL);
398	    global.define("eastern", Color::EASTERN);
399	    global.define("purple", Color::PURPLE);
400	    global.define("fuchsia", Color::FUCHSIA);
401	    global.define("maroon", Color::MAROON);
402	    global.define("red", Color::RED);
403	    global.define("orange", Color::ORANGE);
404	    global.define("yellow", Color::YELLOW);
405	    global.define("olive", Color::OLIVE);
406	    global.define("green", Color::GREEN);
407	    global.define("lime", Color::LIME);
408	    global.define("luma", Color::luma_data());
409	    global.define("oklab", Color::oklab_data());
410	    global.define("oklch", Color::oklch_data());
411	    global.define("rgb", Color::rgb_data());
412	    global.define("cmyk", Color::cmyk_data());
413	    global.define("range", Array::range_data());
414	    global.define("ltr", Dir::LTR);
415	    global.define("rtl", Dir::RTL);
416	    global.define("ttb", Dir::TTB);
417	    global.define("btt", Dir::BTT);
418	    global.define("start", Alignment::START);
419	    global.define("left", Alignment::LEFT);
420	    global.define("center", Alignment::CENTER);
421	    global.define("right", Alignment::RIGHT);
422	    global.define("end", Alignment::END);
423	    global.define("top", Alignment::TOP);
424	    global.define("horizon", Alignment::HORIZON);
425	    global.define("bottom", Alignment::BOTTOM);
426	
427	    // If available, add some items to the global prelude.
428	    global.prelude_path(["format", "html"]);
429	    global.prelude_path(["format", "pdf"]);
430	    global.prelude_path(["format", "bundle", "asset"]);
431	}
