1	//! Typst's standard library.
2	//!
3	//! This crate also contains all of the compiler's central type definitions as
4	//! these are interwoven with the standard library types.
5	//!
6	//! In contrast to the _types,_ most of the compilation _behaviour_ is split out
7	//! into separate crates (`typst-eval`, `typst-realize`, `typst-layout`, etc.)
8	//!
9	//! Note that, unless you are working on the compiler itself, you will rarely
10	//! need to interact with this crate, as it is fully reexported by the `typst`
11	//! crate.
12	
13	extern crate self as typst_library;
14	
15	pub mod diag;
16	pub mod engine;
17	pub mod format;
18	pub mod foundations;
19	pub mod introspection;
20	pub mod layout;
21	pub mod loading;
22	pub mod math;
23	pub mod model;
24	pub mod routines;
25	pub mod symbols;
26	pub mod text;
27	pub mod visualize;
28	
29	use std::fmt::Display;
30	use std::ops::{Deref, Range};
31	use std::str::FromStr;
32	
33	use serde::{Deserialize, Serialize};
34	use typst_syntax::{DiagSpan, DiagSpanKind, FileId, Source};
35	use typst_utils::{LazyHash, SmallBitSet};
36	
37	use crate::diag::FileResult;
38	use crate::format::Format;
39	use crate::foundations::{
40	    Array, Binding, Bytes, Datetime, Dict, Duration, Module, NativeRuleMap, Scope, Styles,
41	};
42	use crate::layout::{Alignment, Dir};
43	use crate::routines::Routines;
44	use crate::text::{Font, FontBook};
45	use crate::visualize::Color;
46	
47	/// The environment in which typesetting occurs.
48	///
49	/// All loading functions (`main`, `source`, `file`, `font`) should perform
50	/// internal caching so that they are relatively cheap on repeated invocations
51	/// with the same argument. [`Source`], [`Bytes`], and [`Font`] are
52	/// all reference-counted and thus cheap to clone.
53	///
54	/// The compiler doesn't do the caching itself because the world has much more
55	/// information on when something can change. For example, fonts typically don't
56	/// change and can thus even be cached across multiple compilations (for
57	/// long-running applications like `typst watch`). Source files on the other
58	/// hand can change and should thus be cleared after each compilation. Advanced
59	/// clients like language servers can also retain the source files and
60	/// [edit](Source::edit) them in-place to benefit from better incremental
61	/// performance.
62	#[comemo::track]
63	pub trait World: Send + Sync {
64	    /// The standard library.
65	    ///
66	    /// Can be created through `Library::build()`.
67	    fn library(&self) -> &LazyHash<Library>;
68	
69	    /// Metadata about all known fonts.
70	    fn book(&self) -> &LazyHash<FontBook>;
71	
72	    /// Get the file id of the main source file.
73	    fn main(&self) -> FileId;
74	
75	    /// Try to access the specified file location as a source file.
76	    fn source(&self, id: FileId) -> FileResult<Source>;
77	
78	    /// Try to access the specified file.
79	    ///
80	    /// For file locations for which [`source`](Self::source) succeeds, this
81	    /// should also succeed. The [`Bytes`] can be cheaply created as a view into
82	    /// an existing [`Source`] through [`Bytes::from_string`].
83	    fn file(&self, id: FileId) -> FileResult<Bytes>;
84	
85	    /// Try to access the font with the given index in the font book.
86	    ///
87	    /// Note that the index is not guaranteed to be in bounds of the font book
88	    /// returned by this world's `book()` function. This is the case because
89	    /// this function may be invoked with indices from an outdated or different
90	    /// font book during incremental compilation validation.
91	    fn font(&self, index: usize) -> Option<Font>;
92	
93	    /// Get the current date.
94	    ///
95	    /// If no offset is specified, the local date should be chosen. Otherwise,
96	    /// the UTC date should be chosen with the corresponding offset.
97	    ///
98	    /// If this function returns `None`, Typst's `datetime` function will
99	    /// return an error.
100	    fn today(&self, offset: Option<Duration>) -> Option<Datetime>;
101	}
102	
103	macro_rules! world_impl {
104	    ($W:ident for $ptr:ty) => {
105	        impl<$W: World> World for $ptr {
106	            fn library(&self) -> &LazyHash<Library> {
107	                self.deref().library()
108	            }
109	
110	            fn book(&self) -> &LazyHash<FontBook> {
111	                self.deref().book()
112	            }
113	
114	            fn main(&self) -> FileId {
115	                self.deref().main()
116	            }
117	
118	            fn source(&self, id: FileId) -> FileResult<Source> {
119	                self.deref().source(id)
120	            }
121	
122	            fn file(&self, id: FileId) -> FileResult<Bytes> {
123	                self.deref().file(id)
124	            }
125	
126	            fn font(&self, index: usize) -> Option<Font> {
127	                self.deref().font(index)
128	            }
129	
130	            fn today(&self, offset: Option<Duration>) -> Option<Datetime> {
131	                self.deref().today(offset)
132	            }
133	        }
134	    };
135	}
136	
137	world_impl!(W for std::boxed::Box<W>);
138	world_impl!(W for std::sync::Arc<W>);
139	world_impl!(W for &W);
140	
141	/// Helper methods on [`World`] implementations.
142	pub trait WorldExt {
143	    /// Get the byte range for a span.
144	    ///
145	    /// Returns `None` if the `Span` does not point into any file.
146	    fn range(&self, span: impl Into<DiagSpan>) -> Option<Range<usize>>;
147	}
148	
149	impl<T: World + ?Sized> WorldExt for T {
150	    fn range(&self, span: impl Into<DiagSpan>) -> Option<Range<usize>> {
151	        match span.into().get() {
152	            DiagSpanKind::Detached => None,
153	            DiagSpanKind::Number { id, num, sub_range } => {
154	                self.source(id).ok()?.range(num, sub_range)
155	            }
156	            DiagSpanKind::Range { id: _, range } => Some(range),
157	        }
158	    }
159	}
160	
161	/// Definition of Typst's standard library.
162	///
163	/// To create and configure the standard library, use the `LibraryExt` trait
164	/// and call
165	/// - `Library::default()` for a standard configuration
166	/// - `Library::builder().build()` if you want to customize the library
167	#[derive(Debug, Clone, Hash)]
168	#[non_exhaustive]
169	pub struct Library {
170	    /// Defines implementation of various Typst compiler routines as a table of
171	    /// function pointers.
172	    pub routines: &'static Routines,
173	    /// The module that contains the definitions that are available everywhere.
174	    pub global: Module,
175	    /// The module that contains the definitions available in math mode.
176	    pub math: Module,
177	    /// The default style properties (for page size, font selection, and
178	    /// everything else configurable via set and show rules).
179	    pub styles: Styles,
180	    /// The built-in show rules.
181	    pub rules: NativeRuleMap,
182	    /// The standard library as a value. Used to provide the `std` module.
183	    pub std: Binding,
184	    /// In-development features that were enabled.
185	    pub features: Features,
186	    /// Registered [export formats](crate::format).
187	    pub formats: Vec<Format>,
188	}
189	
190	/// Configurable builder for the standard library.
191	///
192	/// Constructed via the `LibraryExt` trait.
193	#[derive(Debug, Clone)]
194	pub struct LibraryBuilder {
195	    routines: &'static Routines,
196	    inputs: Option<Dict>,
197	    features: Features,
198	    formats: Vec<Format>,
199	}
200	
201	impl LibraryBuilder {
202	    /// Creates a new builder.
203	    #[doc(hidden)]
204	    pub fn from_routines(
205	        routines: &'static Routines,
206	        formats: impl IntoIterator<Item = Format>,
207	    ) -> Self {
208	        Self {
209	            routines,
210	            inputs: None,
211	            features: Features::default(),
212	            formats: formats.into_iter().collect(),
213	        }
214	    }
215	
216	    /// Configure the inputs visible through `sys.inputs`.
217	    pub fn with_inputs(mut self, inputs: Dict) -> Self {
218	        self.inputs = Some(inputs);
219	        self
220	    }
221	
222	    /// Configure in-development features that should be enabled.
223	    ///
224	    /// No guarantees whatsover!
225	    pub fn with_features(mut self, features: Features) -> Self {
226	        self.features = features;
227	        self
228	    }
229	
230	    /// Consumes the builder and returns a `Library`.
231	    pub fn build(self) -> Library {
232	        let math = math::module();
233	        let inputs = self.inputs.unwrap_or_default();
234	        let global = global(&self.formats, math.clone(), inputs);
235	        let mut rules = (self.routines.rules)();
236	        for format in &self.formats {
237	            format.register_rules(&mut rules);
238	        }
239	        Library {
240	            routines: self.routines,
241	            global: global.clone(),
242	            math,
243	            styles: Styles::new(),
244	            rules,
245	            std: Binding::detached(global),
246	            features: self.features,
247	            formats: self.formats,
248	        }
249	    }
250	}
251	
252	/// A selection of in-development features that should be enabled.
253	///
254	/// Can be collected from an iterator of [`Feature`]s.
255	#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
256	pub struct Features(SmallBitSet);
257	
258	impl Features {
259	    /// Creates an instance where all features are enabled.
260	    pub fn all() -> Self {
261	        Feature::all().collect()
262	    }
263	
264	    /// Creates an instance where no features are enabled.
265	    pub fn none() -> Self {
266	        Self::default()
267	    }
268	
269	    /// Check whether the given feature is enabled.
270	    pub fn is_enabled(&self, feature: Feature) -> bool {
271	        self.0.contains(feature as usize)
272	    }
273	}
274	
275	impl FromIterator<Feature> for Features {
276	    fn from_iter<T: IntoIterator<Item = Feature>>(iter: T) -> Self {
277	        let mut set = SmallBitSet::default();
278	        for feature in iter {
279	            set.insert(feature as usize);
280	        }
281	        Self(set)
282	    }
283	}
284	
285	/// An in-development feature that should be enabled.
286	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
