1	//! Specify configurable export formats.
2	//!
3	//! All export formats have to be registered in [`Library::formats`], by passing
4	//! them to the `typst` crate's
5	//! `LibraryExt::new()` or `LibraryExt::builder()` methods.
6	//!
7	//! Each [`Format`] has an associated [`FormatElement`] with a [`FormatOptions`]
8	//! type. The format element will be defined on the `std.format` binding, making
9	//! it available to set rules.
10	//!
11	//! The options are stored in the compiled document's [`DocumentFormatOptions`]
12	//! and can be accessed using the [`Document::options()`] trait method. The
13	//! concrete type can be retrieved using [`DocumentFormatOptions::get()`]
14	//! providing the format element as a generic parameter.
15	//!
16	//! # Example
17	//! ```
18	//! use typst_library::Library;
19	//! use typst_library::diag::{SourceResult, bail};
20	//! use typst_library::engine::Engine;
21	//! use typst_library::format::{Complete, Fields, Format, FormatElement, Populate};
22	//! use typst_library::foundations::{Args, Construct, Content, StyleChain, elem};
23	//! use typst_library::model::Document;
24	//! use typst_syntax::Spanned;
25	//!
26	//! // This can be passed to `Library::new` as `Format::new::<Epub>()` to
27	//! // register the format.
28	//! #[elem(Construct)]
29	//! pub struct Epub {
30	//!     #[default]
31	//!     pub pretty: bool
32	//! }
33	//!
34	//! impl FormatElement for Epub {
35	//!     type Options = EpubFormatOptions;
36	//! }
37	//!
38	//! impl Construct for Epub {
39	//!     fn construct(_: &mut Engine, args: &mut Args) -> SourceResult<Content> {
40	//!         bail!(args.span, "cannot be constructed manually")
41	//!     }
42	//! }
43	//!
44	//! #[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
45	//! pub struct EpubFormatOptions<T: Fields = Complete> {
46	//!     pub pretty: T::Value<Epub, { Epub::pretty.index() }>,
47	//! }
48	//!
49	//! impl Populate for EpubFormatOptions {
50	//!     fn populate(&mut self, styles: Spanned<StyleChain>) {
51	//!         // The `SpannedValue::populate` call automatically stores the span
52	//!         // of the specific set rule.
53	//!         self.pretty.populate(styles);
54	//!     }
55	//! }
56	//!
57	//!
58	//! // In the export crate.
59	//! fn export_epub(doc: impl Document) {
60	//!     let options = doc.options().get::<Epub>();
61	//!     // Export an EPUB here...
62	//! }
63	//! ```
64	//!
65	//! # Internals
66	//! The [`FormatOptions`] as top-level set-rules have to be special-cased and
67	//! are handled in a similar way as the [`DocumentInfo`], through the
68	//! [`RealizationKind::Document`].
69	//!
70	//! [`Library::formats`]: crate::Library::formats
71	//! [`Document::options()`]: crate::model::Document::options()
72	//! [`DocumentInfo`]: crate::model::DocumentInfo
73	//! [`RealizationKind::Document`]: crate::routines::RealizationKind::Document
74	
75	use std::any::{Any, TypeId};
76	use std::fmt::Debug;
77	use std::hash::Hash;
78	use std::marker::PhantomData;
79	
80	use ecow::EcoVec;
81	use typst_syntax::{Span, Spanned};
82	
83	use crate::Feature;
84	use crate::foundations::{
85	    Element, Field, Module, NativeElement, NativeRuleMap, Scope, SettableProperty,
86	    StyleChain,
87	};
88	
89	/// The global `format` module on which all registered formats will be defined.
90	pub fn module(formats: &[Format]) -> Module {
91	    let mut format = Scope::deduplicating();
92	    format.start_category(crate::Category::Format);
93	
94	    for f in formats {
95	        let binding =
96	            format.define(f.elem.name(), f.elem).with_documentation(f.elem.into());
97	        if let Some(feature) = f.feature {
98	            binding.with_feature(feature);
99	        }
100	    }
101	
102	    Module::new("format", format)
103	}
104	
105	/// An export format with an associated [`FormatElement`].
106	///
107	/// See the [module level](self) docs for more information.
108	#[derive(Debug, Clone, Hash)]
109	pub struct Format {
110	    pub elem: Element,
111	    options: fn() -> FormatOptions,
112	    feature: Option<Feature>,
113	    rules: Option<fn(&mut NativeRuleMap)>,
114	}
115	
116	impl Format {
117	    /// Create a new format with an associated [`FormatElement`].
118	    pub const fn new<E: FormatElement>() -> Self {
119	        Self {
120	            elem: E::ELEM,
121	            options: || E::Options::default().into(),
122	            feature: None,
123	            rules: None,
124	        }
125	    }
126	
127	    /// Gate the format behind a feature flag.
128	    pub const fn with_feature(mut self, feature: Feature) -> Self {
129	        self.feature = Some(feature);
130	        self
131	    }
132	
133	    /// Add format specific rules that will be registered.
134	    pub const fn with_rules(mut self, register: fn(&mut NativeRuleMap)) -> Self {
135	        self.rules = Some(register);
136	        self
137	    }
138	
139	    /// Get the default format options of this format.
140	    pub fn default_options(&self) -> FormatOptions {
141	        (self.options)()
142	    }
143	
144	    /// Register the rules specific to this format.
145	    pub fn register_rules(&self, rules: &mut NativeRuleMap) {
146	        if let Some(register) = self.rules {
147	            register(rules);
148	        }
149	    }
150	}
151	
152	/// An export format element with associated options that can be configured
153	/// using set rules.
154	///
155	/// See the [module level](self) docs for more information.
156	pub trait FormatElement: NativeElement {
157	    type Options: Populate + Default + Clone + Hash;
158	}
159	
160	/// A type that can be populated from a [`StyleChain`].
161	///
162	/// This is used inside [`FormatOptions`].
163	pub trait Populate: Debug + Any + Send + Sync + 'static {
164	    /// Populate this type with details from the given local styles.
165	    fn populate(&mut self, styles: Spanned<StyleChain>);
166	}
167	
168	impl Populate for () {
169	    fn populate(&mut self, _: Spanned<StyleChain>) {}
170	}
171	
172	trait Bounds: Populate {
173	    fn dyn_clone(&self) -> Box<dyn Bounds>;
174	    fn dyn_hash(&self, state: &mut dyn std::hash::Hasher);
175	}
176	
177	impl<T> Bounds for T
178	where
179	    T: Populate + Clone + Hash,
180	{
181	    fn dyn_clone(&self) -> Box<dyn Bounds> {
182	        Box::new(self.clone())
183	    }
184	
185	    fn dyn_hash(&self, mut state: &mut dyn std::hash::Hasher) {
186	        // Also hash the TypeId since values with different types but
187	        // equal data should be different.
188	        TypeId::of::<Self>().hash(&mut state);
189	        self.hash(&mut state);
190	    }
191	}
192	
193	/// A list of format options that have been configured by the document.
194	///
195	/// See the [module level](self) docs for more information.
196	#[derive(Debug, Clone, Hash)]
197	pub struct DocumentFormatOptions(EcoVec<FormatOptions>);
198	
199	impl DocumentFormatOptions {
200	    /// Initialize default format options from a list of formats.
201	    pub fn new(formats: &[Format]) -> Self {
202	        Self(formats.iter().map(Format::default_options).collect())
203	    }
204	
205	    /// Get a concrete format option type.
206	    ///
207	    /// For example with `typst_pdf`, the `PdfFormatOptions` can be retrieved
208	    /// like this on a compiled document.
209	    /// ```rust,ignore
210	    /// let pdf_options = document.options().get::<typst_pdf::Pdf>();
211	    /// ```
212	    pub fn get<T: FormatElement>(&self) -> &T::Options {
213	        self.0
214	            .iter()
215	            .find_map(FormatOptions::downcast::<T>)
216	            .unwrap_or_else(|| {
217	                let format = std::any::type_name::<T>();
218	                let options = std::any::type_name::<T::Options>();
219	                panic!(
220	                    "format `{format}` with options `{options}` not found\n\
221	                     hint: if you're a developer, you need to register `Library::formats`"
222	                );
223	            })
224	    }
225	
226	    /// Populate the format options with details from the given styles.
227	    pub fn populate(&mut self, styles: Spanned<StyleChain>) {
228	        for o in self.0.make_mut() {
229	            o.populate(styles);
230	        }
231	    }
232	}
233	
234	/// Format options that have been configured by the document.
235	///
236	/// See the [module level](self) docs for more information.
237	pub struct FormatOptions(Box<dyn Bounds>);
238	
239	impl FormatOptions {
240	    /// Populate these options from the spanned styles.
241	    pub fn populate(&mut self, styles: Spanned<StyleChain>) {
242	        self.0.populate(styles);
243	    }
244	
245	    /// Attempt to downcast this option to a concrete format option type.
246	    pub fn downcast<T: FormatElement>(&self) -> Option<&T::Options> {
247	        let inner: &dyn Bounds = &*self.0;
248	        (inner as &dyn Any).downcast_ref()
249	    }
250	}
251	
252	impl<T> From<T> for FormatOptions
253	where
254	    T: Populate + Clone + Hash + Debug + Send + Sync + 'static,
255	{
256	    fn from(value: T) -> Self {
257	        Self(Box::new(value))
258	    }
259	}
260	
261	impl Clone for FormatOptions {
262	    fn clone(&self) -> Self {
263	        Self(self.0.dyn_clone())
264	    }
265	}
266	
267	impl Hash for FormatOptions {
268	    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
269	        self.0.dyn_hash(state);
270	    }
271	}
272	
273	impl Debug for FormatOptions {
274	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
275	        self.0.fmt(f)
276	    }
277	}
278	
279	/// A trait that allows specifying [`Complete`] and [`Partial`] types.
280	///
281	/// Types can take a generic marker and wrap their fields in the
282	/// [`Fields::Value`] type, which will either wrap them in an `Option` for the
283	/// [`Partial`] tag or required for the [`Complete`] tag.
284	///
285	/// See the [module level](self) docs for more information.
286	pub trait Fields: Default {
287	    type Value<E, const I: u8>: Debug + Default + Clone + Eq + Hash
288	    where
289	        E: SettableProperty<I>,
290	        E::Type: Debug + Clone + Eq + Hash;
291	}
292	
293	/// Marker for types with fully resolved fields.
294	#[derive(Debug, Default, Copy, Clone, Eq, PartialEq, Hash)]
295	pub struct Complete;
296	
297	impl Fields for Complete {
298	    type Value<E, const I: u8>
299	        = SpannedValue<E, I>
300	    where
301	        E: SettableProperty<I>,
302	        E::Type: Debug + Clone + Eq + Hash;
303	}
304	
305	/// A [`Spanned`] value that is associtated with a specific [`Field`] of an
306	/// element. This allows reusing the [`Default`] value specified on the element,
307	/// by reading from an empty [`StyleChain`].
308	#[derive(Debug, Clone, Hash)]
309	pub struct SpannedValue<E, const I: u8>
310	where
311	    E: SettableProperty<I>,
312	{
313	    /// The format element's field this value should be read from.
314	    field: PhantomData<Field<E, I>>,
315	    pub v: E::Type,
316	    pub span: Span,
317	}
318	
319	impl<E, const I: u8> SpannedValue<E, I>
320	where
321	    E: SettableProperty<I>,
322	{
323	    /// Create a new spanned value.
324	    pub fn new(v: E::Type, span: Span) -> Self {
325	        Self { span, v, field: PhantomData }
326	    }
327	
328	    /// Create a new spanned value with a detached span.
329	    pub fn detached(v: E::Type) -> Self {
330	        Self::new(v, Span::detached())
331	    }
332	
333	    /// Populate this value from the given local styles.
334	    /// If the field has been set, this will also update the span.
335	    pub fn populate(&mut self, styles: Spanned<StyleChain>) {
336	        if styles.v.has(Field::<E, I>::new()) {
337	            *self =
338	                SpannedValue::new(styles.v.get_cloned(Field::<E, I>::new()), styles.span);
339	        }
340	    }
341	}
342	
343	impl<E, const I: u8> Default for SpannedValue<E, I>
344	where
345	    E: SettableProperty<I>,
346	    E::Type: Debug + Clone + Eq + Hash,
347	{
348	    fn default() -> Self {
349	        Self::new(
350	            StyleChain::default().get_cloned(Field::<E, I>::new()),
351	            Span::detached(),
352	        )
353	    }
354	}
355	
356	impl<E, const I: u8> Copy for SpannedValue<E, I>
357	where
358	    E: SettableProperty<I>,
359	    E::Type: Copy,
360	{
361	}
362	
363	impl<E, const I: u8> Eq for SpannedValue<E, I>
364	where
365	    E: SettableProperty<I>,
366	    E::Type: Eq,
367	{
368	}
369	
370	impl<E, const I: u8> PartialEq for SpannedValue<E, I>
371	where
372	    E: SettableProperty<I>,
373	    E::Type: PartialEq,
374	{
375	    fn eq(&self, other: &Self) -> bool {
376	        self.v == other.v && self.span == other.span
377	    }
378	}
379	
380	impl<E, const I: u8> From<Spanned<E::Type>> for SpannedValue<E, I>
381	where
382	    E: SettableProperty<I>,
383	{
384	    fn from(value: Spanned<E::Type>) -> Self {
385	        Self::new(value.v, value.span)
386	    }
387	}
388	
389	/// Marker for types with optional/partial fields.
390	#[derive(Debug, Default, Copy, Clone, Eq, PartialEq, Hash)]
391	pub struct Partial;
392	
393	impl Fields for Partial {
394	    type Value<E, const I: u8>
395	        = Option<E::Type>
396	    where
397	        E: SettableProperty<I>,
398	        E::Type: Debug + Clone + Eq + Hash;
399	}
400	
401	impl Partial {
402	    /// If present, returns the partial value with a detached span, otherwise
403	    /// the default value is returned.
404	    pub fn resolve<E, const I: u8>(
405	        partial: <Partial as Fields>::Value<E, I>,
406	        default: <Complete as Fields>::Value<E, I>,
407	    ) -> <Complete as Fields>::Value<E, I>
408	    where
409	        E: SettableProperty<I>,
410	        E::Type: Debug + Copy + Clone + Eq + Hash,
411	    {
412	        partial.map(SpannedValue::detached).unwrap_or(default)
413	    }
414	
415	    /// If present, returns the partial value with a detached span, otherwise
416	    /// the default value is returned.
417	    pub fn resolve_cloned<E, const I: u8>(
418	        partial: &<Partial as Fields>::Value<E, I>,
419	        default: &<Complete as Fields>::Value<E, I>,
420	    ) -> <Complete as Fields>::Value<E, I>
421	    where
422	        E: SettableProperty<I>,
423	        E::Type: Debug + Clone + Eq + Hash,
424	    {
425	        partial
426	            .clone()
427	            .map(SpannedValue::detached)
428	            .unwrap_or_else(|| default.clone())
429	    }
430	}
431

