197	/// Deduplicate diagnostics.
198	fn deduplicate(mut diags: EcoVec<SourceDiagnostic>) -> EcoVec<SourceDiagnostic> {
199	    let mut unique = FxHashSet::default();
200	    diags.retain(|diag| {
201	        let hash = typst_utils::hash128(&(&diag.span, &diag.message));
202	        unique.insert(hash)
203	    });
204	    diags
205	}
