207	/// Adds useful hints when the main source file couldn't be read
208	/// and returns the final diagnostic.
209	fn hint_invalid_main_file(
210	    world: Tracked<dyn World + '_>,
211	    file_error: FileError,
212	    input: FileId,
213	) -> EcoVec<SourceDiagnostic> {
214	    let is_utf8_error = matches!(file_error, FileError::InvalidUtf8);
215	    let mut diagnostic =
216	        SourceDiagnostic::error(Span::detached(), EcoString::from(file_error));
217	
218	    // Attempt to provide helpful hints for UTF-8 errors. Perhaps the user
219	    // mistyped the filename. For example, they could have written "file.pdf"
220	    // instead of "file.typ".
221	    if is_utf8_error {
222	        match input.vpath().extension() {
223	            // No hints if the file is already a .typ file. The file is indeed
224	            // just invalid.
225	            Some("typ") => return eco_vec![diagnostic],
226	
227	            Some(ext) => {
228	                diagnostic.hint(eco_format!(
229	                    "a file with the `.{ext}` extension is not usually a Typst file",
230	                ));
231	            }
232	
233	            None => {
234	                diagnostic
235	                    .hint("a file without an extension is not usually a Typst file");
236	            }
237	        }
238	
239	        if world.source(input.map(|p| p.with_extension("typ")).intern()).is_ok() {
240	            diagnostic.hint("check if you meant to use the `.typ` extension instead");
241	        }
242	    }
243	
244	    eco_vec![diagnostic]
245	}
