289	/// Provides ways to construct a [`Library`].
290	pub trait LibraryExt {
291	    /// Creates the default library.
292	    ///
293	    /// Requires passing in all formats that should be registered, see
294	    /// [`Self::builder()`]
295	    #[expect(clippy::new_ret_no_self)]
296	    fn new(formats: impl IntoIterator<Item = Format>) -> Library;
297	
298	    /// Creates a builder for configuring a library.
299	    ///
300	    /// Requires passing in all formats that should be registered.
301	    /// ```
302	    /// use typst::{Library, LibraryExt};
303	    ///
304	    /// Library::builder([
305	    ///     typst_html::FORMAT,
306	    ///     typst_pdf::FORMAT,
307	    ///     typst_svg::FORMAT,
308	    ///     typst_render::FORMAT,
309	    ///     typst_bundle::FORMAT,
310	    /// ]);
311	    /// ```
312	    fn builder(formats: impl IntoIterator<Item = Format>) -> LibraryBuilder;
313	}
314	
315	impl LibraryExt for Library {
316	    fn new(formats: impl IntoIterator<Item = Format>) -> Library {
317	        Self::builder(formats).build()
318	    }
319	
320	    fn builder(formats: impl IntoIterator<Item = Format>) -> LibraryBuilder {
321	        LibraryBuilder::from_routines(&ROUTINES, formats)
322	    }
323	}
