126	/// The shared, unmemoized implementation of `html_document` and
127	/// `html_document_for_bundle`.
128	#[expect(clippy::too_many_arguments)]
129	fn html_document_common(
130	    world: Tracked<dyn World + '_>,
131	    library: &LazyHash<Library>,
132	    introspector: Tracked<dyn Introspector + '_>,
133	    traced: Tracked<Traced>,
134	    sink: TrackedMut<Sink>,
135	    route: Tracked<Route>,
136	    content: &Content,
137	    locator: Locator,
138	    styles: StyleChain,
139	) -> SourceResult<HtmlDocument> {
140	    let introspector = Protected::from_raw(introspector);
141	    let mut locator = locator.split();
142	    let mut engine = Engine {
143	        library,
144	        world,
145	        introspector,
146	        traced,
147	        sink,
148	        route: Route::extend(route).unnested(),
149	    };
150	
151	    // Create this upfront to make it as stable as possible.
152	    let footnote_locator = locator.next(&());
153	
154	    // Mark the external styles as "outside" so that they are valid at the
155	    // document level.
156	    let styles = styles.to_map().outside();
157	    let styles = StyleChain::new(&styles);
158	    let arenas = Arenas::default();
159	
160	    let mut info = DocumentInfo::default();
161	    info.populate(styles);
162	    info.populate_locale(styles);
163	    let mut options = DocumentFormatOptions::new(&library.formats);
164	    options.populate(Spanned::detached(styles));
165	
166	    let children = (engine.library.routines.realize)(
167	        RealizationKind::Document { info: &mut info, options: &mut options },
168	        &mut engine,
169	        &mut locator,
170	        &arenas,
171	        content,
172	        styles,
173	    )?;
174	
175	    let nodes = crate::convert::convert_to_nodes(
176	        &mut engine,
177	        &mut locator,
178	        children.iter().copied(),
179	        ConversionLevel::Block,
180	        Whitespace::Normal,
181	    )?;
182	
183	    let mut output = finalize_dom(
184	        &mut engine,
185	        nodes,
186	        &info,
187	        footnote_locator,
188	        StyleChain::new(&Styles::root(&children, styles)),
189	    )?;
190	
191	    // Since `finalize_dom` might have inserted more DOM nodes that have styles,
192	    // the styles must be resolved last.
193	    css::resolve_inline_styles(output.root_mut());
194	
195	    let has_equations = !engine
196	        .introspect(QueryIntrospection(EquationElem::ELEM.select(), Span::detached()))
197	        .is_empty();
198	
199	    if has_equations {
200	        let root = output.root_mut();
201	
202	        let head = root.children.make_mut().iter_mut().find_map(|node| match node {
203	            HtmlNode::Element(elem) if elem.tag == tag::head => Some(elem),
204	            _ => None,
205	        });
206	
207	        // TODO: this becomes an error when html fragments are supported
208	        let head = head.expect("head to be present in document output");
209	
210	        head.children.push(
211	            HtmlElement::new(tag::style)
212	                .with_children(eco_vec![HtmlNode::Text(
213	                    EQUATION_CSS_STYLES.clone(),
214	                    Span::detached(),
215	                )])
216	                .into(),
217	        );
218	    }
219	
220	    Ok(HtmlDocument::new(output, info, options))
221	}
