223	/// The introspectible output of HTML compilation.
224	#[derive(Debug, Clone)]
225	pub struct HtmlOutput {
226	    nodes: EcoVec<HtmlNode>,
227	    root_index: usize,
228	}
229	
230	impl HtmlOutput {
231	    /// All nodes.
232	    pub fn nodes(&self) -> &[HtmlNode] {
233	        &self.nodes
234	    }
235	
236	    /// The root note.
237	    pub fn root(&self) -> &HtmlElement {
238	        match &self.nodes[self.root_index] {
239	            HtmlNode::Element(root) => root,
240	            _ => panic!("expected HTML element"),
241	        }
242	    }
243	
244	    /// The root note, mutably.
245	    pub fn root_mut(&mut self) -> &mut HtmlElement {
246	        match &mut self.nodes.make_mut()[self.root_index] {
247	            HtmlNode::Element(root) => root,
248	            _ => panic!("expected HTML element"),
249	        }
250	    }
251	
252	    /// The document's root HTML element, in its containing node wrapper.
253	    pub fn root_node(&self) -> &HtmlNode {
254	        &self.nodes[self.root_index]
255	    }
256	}
