258	/// Wrap the user generated HTML in `<html>`, `<body>` or both if needed.
259	///
260	/// Returns a vector containing outer introspection tags and the HTML root element.
261	/// A direct reference to the root element is also returned.
262	fn finalize_dom(
263	    engine: &mut Engine,
264	    nodes: EcoVec<HtmlNode>,
265	    info: &DocumentInfo,
266	    footnote_locator: Locator<'_>,
267	    footnote_styles: StyleChain<'_>,
268	) -> SourceResult<HtmlOutput> {
269	    let count = nodes.iter().filter(|node| !matches!(node, HtmlNode::Tag(_))).count();
270	
271	    let mut needs_body = true;
272	    for (idx, node) in nodes.iter().enumerate() {
273	        let HtmlNode::Element(elem) = node else { continue };
274	        let tag = elem.tag;
275	        match (tag, count) {
276	            (tag::html, 1) => {
277	                footnotes_unsupported_with_custom_dom(engine)?;
278	                return Ok(HtmlOutput { nodes, root_index: idx });
279	            }
280	            (tag::body, 1) => {
281	                footnotes_unsupported_with_custom_dom(engine)?;
282	                needs_body = false;
283	            }
284	            (tag::html | tag::body, _) => bail!(
285	                elem.span,
286	                "`{}` element must be the only element in the document",
287	                elem.tag,
288	            ),
289	            _ => {}
290	        }
291	    }
292	
293	    let body = if needs_body {
294	        let mut body = HtmlElement::new(tag::body).with_children(nodes);
295	        let footnotes = crate::fragment::html_block_fragment(
296	            engine,
297	            FootnoteContainer::shared(),
298	            footnote_locator,
299	            footnote_styles,
300	            Whitespace::Normal,
301	        )?;
302	        body.children.extend(footnotes);
303	        eco_vec![body.into()]
304	    } else {
305	        nodes
306	    };
307	
308	    let mut html = HtmlElement::new(tag::html)
309	        .with_attr(attr::lang, info.locale.unwrap_or_default().rfc_3066());
310	    let head = head_element(info);
311	    html.children.push(head.into());
312	    html.children.extend(body);
313	    Ok(HtmlOutput { nodes: eco_vec![html.into()], root_index: 0 })
314	}
315	
316	/// Generate a `<head>` element.
317	fn head_element(info: &DocumentInfo) -> HtmlElement {
318	    let mut children = EcoVec::new();
319	
320	    children.push(HtmlElement::new(tag::meta).with_attr(attr::charset, "utf-8").into());
321	
322	    children.push(
323	        HtmlElement::new(tag::meta)
324	            .with_attr(attr::name, "viewport")
325	            .with_attr(attr::content, "width=device-width, initial-scale=1")
326	            .into(),
327	    );
328	
329	    if let Some(title) = &info.title {
330	        children.push(
331	            HtmlElement::new(tag::title)
332	                .with_children(eco_vec![HtmlNode::Text(title.clone(), Span::detached())])
333	                .into(),
334	        );
335	    }
336	
337	    if let Some(description) = &info.description {
338	        children.push(
339	            HtmlElement::new(tag::meta)
340	                .with_attr(attr::name, "description")
341	                .with_attr(attr::content, description.clone())
342	                .into(),
343	        );
344	    }
345	
346	    for author in &info.author {
347	        children.push(
348	            HtmlElement::new(tag::meta)
349	                .with_attr(attr::name, "author")
350	                .with_attr(attr::content, author)
351	                .into(),
352	        );
353	    }
354	
355	    if !info.keywords.is_empty() {
356	        children.push(
357	            HtmlElement::new(tag::meta)
358	                .with_attr(attr::name, "keywords")
359	                .with_attr(attr::content, info.keywords.join(", "))
360	                .into(),
361	        );
362	    }
363	
364	    HtmlElement::new(tag::head).with_children(children)
365	}
366	
367	/// Fails with an error if there are footnotes.
368	fn footnotes_unsupported_with_custom_dom(engine: &mut Engine) -> SourceResult<()> {
369	    let markers = engine
370	        .introspect(QueryIntrospection(FootnoteMarker::ELEM.select(), Span::detached()));
371	
372	    if markers.is_empty() {
373	        return Ok(());
374	    }
375	
376	    Err(markers
377	        .iter()
378	        .map(|marker| {
379	            error!(
380	                marker.span(),
381	                "footnotes are not currently supported in combination \
382	                 with a custom `<html>` or `<body>` element";
383	                hint: "you can still use footnotes with a custom footnote show rule";
384	            )
385	        })
386	        .collect())
387	}
