/// An HTML document.
///
/// Unlike the `PagedDocument`, this does not implement `Hash` because the HTML
/// introspector is neither hashable nor guaranteed to be 100% derived from the
/// output (due to the presence of `root_mut` which is used for cross-linking).
#[derive(Debug, Clone)]
pub struct HtmlDocument {
    output: HtmlOutput,
    info: DocumentInfo,
    options: DocumentFormatOptions,
    introspector: Arc<HtmlIntrospector>,
}

impl HtmlDocument {
    /// Creates a new HTML document from its parts.
    ///
    /// Internally builds the introspector.
    pub fn new(
        output: HtmlOutput,
        info: DocumentInfo,
        options: DocumentFormatOptions,
    ) -> Self {
        let introspector = HtmlIntrospector::new(output.nodes());
        Self {
            output,
            info,
            options,
            introspector: Arc::new(introspector),
        }
    }

    /// The document's root HTML element.
    pub fn root(&self) -> &HtmlElement {
        self.output.root()
    }

    /// The document's root HTML element, mutably.
    ///
    /// Technically, mutating the root can mess up the introspector. This should
    /// be fixed at some point (<https://github.com/typst/typst/issues/7951>).
    pub fn root_mut(&mut self) -> &mut HtmlElement {
        self.output.root_mut()
    }

    /// The document's root HTML element, in its containing node wrapper.
    pub fn root_node(&self) -> &HtmlNode {
        self.output.root_node()
    }

    /// Details about the document, mutably.
    pub fn info_mut(&mut self) -> &mut DocumentInfo {
        &mut self.info
    }

    /// Provides the ability to execute queries on the document.
    pub fn introspector(&self) -> &Arc<HtmlIntrospector> {
        &self.introspector
    }

    /// Provides the ability to execute queries on the document.
    pub fn introspector_mut(&mut self) -> &mut HtmlIntrospector {
        Arc::make_mut(&mut self.introspector)
    }
}

impl Document for HtmlDocument {
    fn info(&self) -> &DocumentInfo {
        &self.info
    }

    fn options(&self) -> &DocumentFormatOptions {
        &self.options
    }
}

impl Output for HtmlDocument {
    fn introspector(&self) -> &dyn Introspector {
        self.introspector.as_ref()
    }

    fn target() -> Target {
        Target::Html
    }

    fn create(
        engine: &mut Engine,
        content: &Content,
        styles: StyleChain,
    ) -> SourceResult<Self> {
        crate::html_document(engine, content, styles)
    }
}

/// A child of an HTML element.
#[derive(Debug, Clone, Hash)]
pub enum HtmlNode {
    /// An introspectable element that produced something within this node.
    Tag(Tag),
    /// Plain text.

impl SystemWorld {
    /// Creates a new system world.
    pub fn new(
        input: Option<&Input>,
        world_args: &'static WorldArgs,
        process_args: &ProcessArgs,
    ) -> Result<Self, WorldCreationError> {
        // Set up the thread pool.
        if let Some(jobs) = process_args.jobs {
            rayon::ThreadPoolBuilder::new()
                .num_threads(jobs)
                .use_current_thread()
                .build_global()
                .ok();
        }

        let library = {
            // Convert the input pairs to a dictionary.
            let inputs: Dict = world_args
                .inputs
                .iter()
                .map(|(k, v)| (k.as_str().into(), v.as_str().into_value()))
                .collect();

            let features =
                process_args.features.iter().copied().map(Into::into).collect();

            Library::builder([
                typst_html::FORMAT,
                typst_pdf::FORMAT,
                typst_svg::FORMAT,
                typst_render::FORMAT,
                typst_bundle::FORMAT,
            ])
            .with_inputs(inputs)
            .with_features(features)
            .build()
        };

        let now = match world_args.creation_timestamp {
            Some(time) => Time::fixed_timestamp(time)
                .map_err(|_| WorldCreationError::InvalidTimestamp)?,
            None => Time::system(),
        };

        Ok(Self {
            workdir: std::env::current_dir().ok(),
            library: LazyHash::new(library),
            fonts: LazyLock::new(Box::new(|| {
                crate::fonts::discover_fonts(&world_args.font)
            })),
            files: FileStore::new(SystemFiles::new(input, world_args)?),
            now,
        })
    }

    /// The project root relative to which absolute paths are resolved.
    pub fn root(&self) -> &Path {
        self.files.loader().project.path()
    }

