    link_resolver: Tracked<'a, LateLinkResolver<'a>>,
    /// Whether pretty printing is enabled.
    pretty: bool,
}

impl<'a> Writer<'a> {
    /// Creates a new writer.
    fn new(link_resolver: Tracked<'a, LateLinkResolver<'a>>, pretty: bool) -> Self {
        Self {
            buf: String::new(),
            level: 0,

